BEGIN;
INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'basic', 'multiple_choice', 'What is the purpose of a ''standard depth scale'' or shade-card reference system used in dye houses?', '["To provide a consistent, standardized reference for describing/communicating a target color depth or specific shade across different people and locations","A tool used only to measure fabric width, unrelated to color","A device used exclusively to measure fiber moisture content","A record of employee shift schedules at the dye house"]'::jsonb, 'To provide a consistent, standardized reference for describing/communicating a target color depth or specific shade across different people and locations', 'Standard depth scales and shade cards give dye technicians, buyers, and quality staff a common, consistent visual/numerical reference for describing exact target shades or depths, reducing ambiguity when communicating color requirements across different people, mills, or locations.', 1, '{"standard-depth-scale"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'intermediate', 'multiple_choice', 'What is ''delta E'' (ΔE) commonly used to express in objective shade comparison?', '["A single numerical value representing the overall color difference between two samples, calculated from their measured color coordinates","The exact chemical name of a dye used in a recipe","The total fabric weight difference between two samples","The twist direction difference between two yarns"]'::jsonb, 'A single numerical value representing the overall color difference between two samples, calculated from their measured color coordinates', 'Delta E (ΔE) condenses the differences across multiple color dimensions (like lightness, hue, chroma) into a single number representing overall perceived color difference between a sample and a standard — widely used as a pass/fail threshold in shade approval (e.g., ΔE below a certain value is considered an acceptable match).', 2, '{"delta-e"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'intermediate', 'multiple_choice', 'Why is a numerical Delta E tolerance (rather than only subjective visual judgment) increasingly used for shade approval between a buyer and a supplier?', '["It provides an objective, quantifiable, and reproducible pass/fail criterion, reducing disputes that can arise from purely subjective human visual assessment","Delta E measurement is always less accurate than simple visual judgment by an experienced person","Numerical tolerances eliminate the need for any lab dip or shade approval process at all","Visual judgment and Delta E measurement always produce identical results with zero possible disagreement"]'::jsonb, 'It provides an objective, quantifiable, and reproducible pass/fail criterion, reducing disputes that can arise from purely subjective human visual assessment', 'Since human color perception can vary between individuals, lighting conditions, and even mood/fatigue, an objective Delta E numerical tolerance gives both buyer and supplier a reproducible, agreed-upon standard for shade acceptance — reducing potential disputes inherent in relying purely on subjective visual comparison.', 2, '{"delta-e-shade-approval"}'::text[]);
COMMIT;
